// Generates host config files from scripts/security-headers.mjs so they never drift:
//   public/_headers  -> Netlify and Cloudflare Pages
//   vercel.json      -> Vercel
// Runs automatically before `npm run build`.
import { writeFileSync } from 'node:fs'
import { cacheRules, securityHeaders } from './security-headers.mjs'

const netlify = [
  '# Generated by scripts/write-host-configs.mjs, do not edit by hand.',
  '/*',
  ...Object.entries(securityHeaders).map(([k, v]) => `  ${k}: ${v}`),
  ...cacheRules.flatMap(([path, value]) => [path, `  Cache-Control: ${value}`]),
  '',
].join('\n')
writeFileSync(new URL('../public/_headers', import.meta.url), netlify)

const toVercel = (pattern) => pattern.replace('/*', '/(.*)')
const vercel = {
  headers: [
    {
      source: '/(.*)',
      headers: Object.entries(securityHeaders).map(([key, value]) => ({ key, value })),
    },
    ...cacheRules.map(([path, value]) => ({
      source: toVercel(path),
      headers: [{ key: 'Cache-Control', value }],
    })),
  ],
}
writeFileSync(new URL('../vercel.json', import.meta.url), `${JSON.stringify(vercel, null, 2)}\n`)

console.log('Wrote public/_headers and vercel.json')
